import { api, node } from './api.js';
import { renderCompactTrace } from './algorithm-view.js';
import { activeTab } from './layout.js';
import { loadParameters,resetCharts,exportChart } from './charts.js';
import { $,resources,bindAnalysis,bindProcess,bindSelection,fail } from './course-ui.js';
async function init(){const ctx=await resources();const target=(window.NLPLAB_PAGE || location.pathname)==='/deep-learning'?'bilstm':'hmm';const start=target==='bilstm'?bindAnalysis(ctx,{trace:true}):null;if(start)bindProcess(ctx);
  async function refresh(){if(activeTab()!==target)return;if(!ctx.available())throw new Error('unavailable：当前模型资源不存在或运行环境缺少依赖。');const version=ctx.version;await loadParameters(ctx.runId()||'latest',Number($('topk').value),$('emission-state').value,()=>version===ctx.version,ctx.model());}
  let demoTimer=0,demoRequest=0;
  async function runDemo(request){if(target!=='hmm'||activeTab()!=='hmm'||request!==demoRequest)return;const text=$('hmm-demo-input').value.trim(),version=ctx.version;if(!text)return;const status=$('hmm-demo-status');status.textContent='正在解码当前短文本…';try{const value=await api('/api/v1/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,tasks:['segmentation'],run_id:ctx.runId()||'latest',segmentation_model:ctx.model()})});if(request!==demoRequest||version!==ctx.version)return;const segmentation=value.segmentation,output=$('hmm-demo-result');output.replaceChildren();const tokens=node('div','','hmm-demo-tokens');segmentation.tokens.forEach((word,index)=>{const chip=node('span',word,'result-token');chip.append(node('small',String(index+1)));tokens.append(chip);});const tags=node('div','','hmm-demo-tags');Array.from(text).forEach((char,index)=>{const cell=node('span','','bmes-cell');cell.dataset.tag=segmentation.tags[index];cell.append(node('span',char),node('small',segmentation.tags[index]));tags.append(cell);});output.append(node('strong','分词结果'),tokens,node('strong','字符 → BMES'),tags);status.textContent=`${ctx.model()} · ${Array.from(text).length} 字符 · ${segmentation.tokens.length} 词 · ${value.elapsed_ms} ms`;
      const trace=await api(`/api/v1/experiments/1/trace?${new URLSearchParams({text,model:ctx.model(),run_id:ctx.runId()||'latest'})}`);if(request!==demoRequest||version!==ctx.version)return;renderCompactTrace($('hmm-demo-trace'),trace);
    }catch(error){if(request===demoRequest&&version===ctx.version){status.textContent='当前短文本解码不可用。';fail(error);}}}
  function scheduleDemo(delay=0){clearTimeout(demoTimer);const request=++demoRequest;if(target!=='hmm')return;$('hmm-demo-result').textContent='等待当前输入的解码结果。';$('hmm-demo-trace').replaceChildren();if(!$('hmm-demo-input').value.trim())return;demoTimer=setTimeout(()=>runDemo(request),delay);}
  bindSelection(ctx,()=>{resetCharts();return refresh().then(()=>scheduleDemo());});for(const id of ['topk','emission-state'])$(id).addEventListener('change',()=>refresh().catch(fail));
  if(target==='hmm'){$('hmm-demo-input').addEventListener('input',()=>scheduleDemo(350));$('hmm-demo-button').addEventListener('click',()=>scheduleDemo());}
  if(target==='hmm'){const descriptions={B:'B 表示词首，下一状态只能是 M 或 E。',M:'M 表示词中，下一状态只能是 M 或 E。',E:'E 表示词尾，下一状态只能是 B 或 S。',S:'S 表示单字词，下一状态只能是 B 或 S。'};for(const button of document.querySelectorAll('.bmes-transition-list button'))button.addEventListener('click',()=>{for(const item of document.querySelectorAll('.bmes-transition-list button'))item.classList.toggle('is-active',item===button);$('bmes-rule-detail').textContent=descriptions[button.dataset.state];});document.querySelector('.bmes-transition-list button')?.click();}
  for(const button of document.querySelectorAll('[data-export]'))button.addEventListener('click',()=>{try{exportChart(button.dataset.export,ctx.modelRun());}catch(e){fail(e);}});
  document.addEventListener('module-tab',()=>{refresh().then(()=>{if(start&&activeTab()===target&&$('original-text').classList.contains('result-empty'))start();if(target==='hmm'&&activeTab()==='hmm')scheduleDemo();}).catch(fail);});await refresh();if(start&&activeTab()===target)start();if(target==='hmm'&&activeTab()==='hmm')scheduleDemo();
}init().catch(fail);
